-- Read-only business snapshots and controlled output; no new economic postings.
CREATE TABLE accounting.customer_statements(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),customer_id uuid NOT NULL,from_date date NOT NULL,to_date date NOT NULL,snapshot jsonb NOT NULL,sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),FOREIGN KEY(company_id,customer_id)REFERENCES crm.customers(company_id,id),CHECK(to_date>from_date AND to_date-from_date<=366),CHECK(sha256=encode(sha256(convert_to(snapshot::text,'UTF8')),'hex')));
CREATE TABLE accounting.operating_report_runs(id uuid PRIMARY KEY,company_id uuid NOT NULL REFERENCES core.companies(id),kind text NOT NULL CHECK(kind IN('PURCHASING','ARAP','INVENTORY','BANKING')),from_date date NOT NULL,to_date date NOT NULL,filters jsonb NOT NULL,snapshot jsonb NOT NULL,sha256 text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),FOREIGN KEY(company_id,id)REFERENCES platform.documents(company_id,id),CHECK(to_date>from_date AND to_date-from_date<=366),CHECK(sha256=encode(sha256(convert_to(snapshot::text,'UTF8')),'hex')));
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['customer_statements','operating_report_runs']LOOP EXECUTE format('ALTER TABLE accounting.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE accounting.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON accounting.%I USING(company_id=core.current_company())WITH CHECK(company_id=core.current_company())',t);EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END LOOP;END$$;
CREATE INDEX ON accounting.customer_statements(company_id,customer_id,created_at DESC,id);
CREATE INDEX ON accounting.operating_report_runs(company_id,kind,created_at DESC,id);
INSERT INTO identity.permissions(code,description)VALUES('accounting.statements.read','Generate/read consolidated customer statements'),('accounting.statements.send','Send authorized customer statements'),('reports.operating.read','Read company-wide financial operating reports'),('reports.operating.export','Export frozen operating report snapshots');
CREATE FUNCTION identity.seed_operating_report_roles(c uuid)RETURNS void LANGUAGE sql SET search_path=pg_catalog AS $$ INSERT INTO identity.role_permissions(company_id,role_id,permission_code)SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND r.code IN('ADMIN','FINANCE')AND p.code IN('accounting.statements.read','accounting.statements.send','reports.operating.read','reports.operating.export')ON CONFLICT DO NOTHING $$;
DO $$DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_operating_report_roles(c);END LOOP;PERFORM set_config('htt.company_id','',true);END$$;
CREATE FUNCTION accounting.require_operating_report(p_kind text)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM purchase.require_access('reports.operating.read');PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.reports.read');
 IF p_kind='PURCHASING'THEN PERFORM purchase.require_access('purchase.orders.read');PERFORM purchase.require_access('purchase.cost.read');
 ELSIF p_kind='INVENTORY'THEN PERFORM purchase.require_access('inventory.cost.read');
 ELSIF p_kind='ARAP'THEN PERFORM purchase.require_access('customers.all');
 ELSIF p_kind='BANKING'THEN PERFORM purchase.require_access('accounting.banks.read');PERFORM purchase.require_access('accounting.bank_statements.read');
 ELSE RAISE EXCEPTION 'Unknown operating report' USING ERRCODE='HR422';END IF;
END$$;
CREATE VIEW accounting.report_advance_events WITH(security_invoker=true)AS WITH raw AS(SELECT a.company_id,'AR'::text AS side,cu.party_id AS party_id,a.receipt_id AS source_document_id,a.amount AS amount FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN crm.customers cu ON cu.company_id=r.company_id AND cu.id=r.customer_id
UNION ALL
SELECT a.company_id,'AR',cu.party_id,x.id,-x.amount FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN crm.customers cu ON cu.company_id=r.company_id AND cu.id=r.customer_id JOIN accounting.advance_applications x ON x.company_id=a.company_id AND x.advance_id=a.id
UNION ALL
SELECT a.company_id,'AR',cu.party_id,x.id,x.amount FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN crm.customers cu ON cu.company_id=r.company_id AND cu.id=r.customer_id JOIN accounting.advance_unapplications x ON x.company_id=a.company_id AND x.advance_id=a.id
UNION ALL
SELECT a.company_id,'AR',cu.party_id,x.id,-a.amount FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN crm.customers cu ON cu.company_id=r.company_id AND cu.id=r.customer_id JOIN accounting.receipt_reversals x ON x.company_id=a.company_id AND x.receipt_id=a.receipt_id
UNION ALL
SELECT a.company_id,'AR',cu.party_id,x.id,-x.amount FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN crm.customers cu ON cu.company_id=r.company_id AND cu.id=r.customer_id JOIN accounting.customer_refunds x ON x.company_id=a.company_id AND x.advance_id=a.id
UNION ALL
SELECT a.company_id,'AR',cu.party_id,v.id,v.amount FROM accounting.customer_advances a JOIN accounting.customer_receipts r ON r.company_id=a.company_id AND r.id=a.receipt_id JOIN crm.customers cu ON cu.company_id=r.company_id AND cu.id=r.customer_id JOIN accounting.customer_refunds x ON x.company_id=a.company_id AND x.advance_id=a.id JOIN accounting.customer_refund_reversals v ON v.company_id=x.company_id AND v.refund_id=x.id
UNION ALL
SELECT a.company_id,'AP'::text AS side,a.party_id AS party_id,a.payment_id AS source_document_id,a.amount AS amount FROM accounting.supplier_advances a 
UNION ALL
SELECT a.company_id,'AP',a.party_id,x.id,-x.amount FROM accounting.supplier_advances a  JOIN accounting.supplier_advance_applications x ON x.company_id=a.company_id AND x.advance_id=a.id
UNION ALL
SELECT a.company_id,'AP',a.party_id,x.id,x.amount FROM accounting.supplier_advances a  JOIN accounting.supplier_advance_unapplications x ON x.company_id=a.company_id AND x.advance_id=a.id
UNION ALL
SELECT a.company_id,'AP',a.party_id,x.id,-a.amount FROM accounting.supplier_advances a  JOIN accounting.supplier_payment_reversals x ON x.company_id=a.company_id AND x.payment_id=a.payment_id
UNION ALL
SELECT a.company_id,'AP',a.party_id,x.id,-x.amount FROM accounting.supplier_advances a  JOIN accounting.supplier_refunds x ON x.company_id=a.company_id AND x.advance_id=a.id
UNION ALL
SELECT a.company_id,'AP',a.party_id,v.id,v.amount FROM accounting.supplier_advances a  JOIN accounting.supplier_refunds x ON x.company_id=a.company_id AND x.advance_id=a.id JOIN accounting.supplier_refund_reversals v ON v.company_id=x.company_id AND v.refund_id=x.id),dates AS(SELECT j.company_id,b.source_document_id,min(j.posting_date)AS posting_date FROM accounting.journal_entries j JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id GROUP BY j.company_id,b.source_document_id)SELECT r.*,d.posting_date FROM raw r JOIN dates d ON d.company_id=r.company_id AND d.source_document_id=r.source_document_id;
GRANT SELECT ON accounting.report_advance_events TO htt_app;
CREATE FUNCTION accounting.require_statement_customer(p_customer uuid)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$BEGIN
 PERFORM sales.require_customer_access('accounting.statements.read',p_customer);PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.reports.read');PERFORM 1 FROM crm.customers WHERE company_id=core.current_company()AND id=p_customer;IF NOT FOUND THEN RAISE EXCEPTION 'Customer unavailable' USING ERRCODE='HT404';END IF;END$$;
REVOKE ALL ON FUNCTION accounting.require_statement_customer(uuid)FROM PUBLIC;GRANT EXECUTE ON FUNCTION accounting.require_statement_customer(uuid)TO htt_app;
CREATE FUNCTION accounting.advance_control_check(p_to date)RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog AS $$
WITH events AS(SELECT coalesce(sum(amount)FILTER(WHERE side='AR'),0)AS ar,coalesce(sum(amount)FILTER(WHERE side='AP'),0)AS ap FROM accounting.report_advance_events WHERE company_id=core.current_company()AND posting_date<p_to),gl AS(SELECT coalesce(sum(l.credit-l.debit)FILTER(WHERE m.purpose='CUSTOMER_ADVANCES'),0)AS ar,coalesce(sum(l.debit-l.credit)FILTER(WHERE m.purpose='SUPPLIER_ADVANCES'),0)AS ap FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.account_mappings m ON m.company_id=l.company_id AND m.account_id=l.account_id AND m.purpose IN('CUSTOMER_ADVANCES','SUPPLIER_ADVANCES')WHERE l.company_id=core.current_company()AND j.posting_date<p_to)SELECT jsonb_build_object('scope','COMPANY_WIDE','customerDifference',(e.ar-g.ar)::text,'supplierDifference',(e.ap-g.ap)::text)FROM events e CROSS JOIN gl g $$;
REVOKE ALL ON FUNCTION accounting.advance_control_check(date)FROM PUBLIC;
CREATE FUNCTION accounting.statement_snapshot(p_customer uuid,p_from date,p_to date)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
DECLARE c uuid:=core.current_company();party uuid;result jsonb;BEGIN
 PERFORM sales.require_customer_access('accounting.statements.read',p_customer);PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.reports.read');
 IF p_from IS NULL OR p_from<'0002-01-01'OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>366 THEN RAISE EXCEPTION 'Use a 1..366 day half-open statement period' USING ERRCODE='HR422';END IF;
 SELECT party_id INTO party FROM crm.customers WHERE company_id=c AND id=p_customer;IF NOT FOUND THEN RAISE EXCEPTION 'Customer unavailable' USING ERRCODE='HT404';END IF;
 WITH ledger AS MATERIALIZED(SELECT j.posting_date,b.source_document_id,d.number,d.document_type,sum(l.debit)AS debit,sum(l.credit)AS credit FROM accounting.journal_lines l JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.accounts a ON a.company_id=l.company_id AND a.id=l.account_id JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.source_document_id WHERE l.company_id=c AND l.party_id=party AND a.control_kind='AR'AND j.posting_date<p_to GROUP BY j.posting_date,b.source_document_id,d.number,d.document_type),
 totals AS(SELECT coalesce(sum(debit-credit)FILTER(WHERE posting_date<p_from),0)AS opening,coalesce(sum(debit)FILTER(WHERE posting_date>=p_from),0)AS debits,coalesce(sum(credit)FILTER(WHERE posting_date>=p_from),0)AS credits,coalesce(sum(debit-credit),0)AS closing FROM ledger),
 movements AS MATERIALIZED(SELECT m.item_line_id,sum(m.amount)AS balance FROM accounting.report_open_item_movements m JOIN accounting.report_control_dates d ON d.company_id=m.company_id AND d.source_document_id=m.source_document_id AND d.side=m.side JOIN sales.invoice_lines il ON il.company_id=m.company_id AND il.id=m.item_line_id JOIN sales.invoices i ON i.company_id=il.company_id AND i.id=il.invoice_id WHERE m.company_id=c AND m.side='AR'AND i.party_id=party AND d.posting_date<p_to GROUP BY m.item_line_id),
 activity AS(SELECT posting_date,source_document_id,number,document_type,debit,credit,(SELECT opening FROM totals)+sum(debit-credit)OVER(ORDER BY posting_date,source_document_id)AS running_balance FROM ledger WHERE posting_date>=p_from),
 openitems AS(SELECT i.id,i.due_on,d.number,sum(m.balance)AS balance FROM movements m JOIN sales.invoice_lines il ON il.company_id=c AND il.id=m.item_line_id JOIN sales.invoices i ON i.company_id=il.company_id AND i.id=il.invoice_id JOIN platform.documents d ON d.company_id=i.company_id AND d.id=i.id GROUP BY i.id,i.due_on,d.number HAVING sum(m.balance)<>0),
 advance AS(SELECT coalesce(sum(amount),0)AS amount FROM accounting.report_advance_events WHERE company_id=c AND side='AR'AND party_id=party AND posting_date<p_to)
 SELECT jsonb_build_object('templateVersion',2,'title','CUSTOMER STATEMENT','companyId',c,'customerId',p_customer,'partyId',party,'currency','AUD','basis','POSTING_DATE','snapshotAt',statement_timestamp(),'from',p_from,'to',p_to,'issuer',(SELECT jsonb_build_object('name',name,'abn',abn,'country',country)FROM core.companies WHERE id=c),'party',(SELECT jsonb_build_object('legalName',legal_name,'abn',abn,'country',country)FROM crm.parties WHERE company_id=c AND id=party),'opening',t.opening::text,'debits',t.debits::text,'credits',t.credits::text,'closing',t.closing::text,'businessBalance',(SELECT coalesce(sum(balance),0)::text FROM movements),'difference',(t.closing-(SELECT coalesce(sum(balance),0)FROM movements))::text,'advanceBalance',a.amount::text,'status',CASE WHEN t.closing=(SELECT coalesce(sum(balance),0)FROM movements)THEN'RECONCILED'ELSE'UNRECONCILED'END,'lines',coalesce((SELECT jsonb_agg(jsonb_build_object('date',posting_date,'documentId',source_document_id,'number',number,'type',document_type,'debit',debit::text,'credit',credit::text,'balance',running_balance::text)ORDER BY posting_date,source_document_id)FROM activity),'[]'::jsonb),'openItems',coalesce((SELECT jsonb_agg(jsonb_build_object('documentId',id,'number',number,'dueOn',due_on,'balance',balance::text)ORDER BY due_on,id)FROM openitems),'[]'::jsonb))INTO result FROM totals t CROSS JOIN advance a;
 IF jsonb_array_length(result->'openItems')>1000 OR jsonb_array_length(result->'lines')>1000 OR octet_length(result::text)>500000 THEN RAISE EXCEPTION 'Statement too large; use a shorter period' USING ERRCODE='HR422';END IF;RETURN result;
END$$;
CREATE FUNCTION accounting.operating_report(p_kind text,p_from date,p_to date,p_party uuid DEFAULT NULL,p_warehouse uuid DEFAULT NULL,p_bank uuid DEFAULT NULL)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog SET jit=off AS $$
DECLARE c uuid:=core.current_company();result jsonb;f jsonb;BEGIN
 PERFORM accounting.require_operating_report(p_kind);
 IF p_from IS NULL OR p_from<'0002-01-01'OR p_to IS NULL OR p_to<=p_from OR p_to-p_from>366 OR p_party IS NOT NULL AND p_kind NOT IN('ARAP','PURCHASING')OR p_warehouse IS NOT NULL AND p_kind<>'INVENTORY'OR p_bank IS NOT NULL AND p_kind<>'BANKING'THEN RAISE EXCEPTION 'Invalid report range or unsupported filter' USING ERRCODE='HR422';END IF;
 IF p_party IS NOT NULL AND NOT EXISTS(SELECT 1 FROM crm.parties WHERE company_id=c AND id=p_party)OR p_warehouse IS NOT NULL AND NOT EXISTS(SELECT 1 FROM catalog.warehouses WHERE company_id=c AND id=p_warehouse)OR p_bank IS NOT NULL AND NOT EXISTS(SELECT 1 FROM accounting.bank_accounts WHERE company_id=c AND id=p_bank)THEN RAISE EXCEPTION 'Report filter unavailable' USING ERRCODE='HT404';END IF;
 IF p_kind='PURCHASING'THEN
 WITH events AS MATERIALIZED(
 SELECT o.id,o.supplier_id,s.party_id,o.warehouse_id,d.business_date AS occurred_on,d.number,'ORDER'::text AS event_type,o.net,o.tax,o.gross FROM purchase.orders o JOIN platform.documents d ON d.company_id=o.company_id AND d.id=o.id JOIN crm.suppliers s ON s.company_id=o.company_id AND s.id=o.supplier_id WHERE o.company_id=c AND o.status<>'DRAFT'
 UNION ALL SELECT r.id,r.supplier_id,s.party_id,r.warehouse_id,d.business_date,d.number,'RECEIPT',sum(l.valuation_amount),0,sum(l.valuation_amount)FROM purchase.receipts r JOIN purchase.receipt_lines l ON l.company_id=r.company_id AND l.receipt_id=r.id JOIN platform.documents d ON d.company_id=r.company_id AND d.id=r.id JOIN crm.suppliers s ON s.company_id=r.company_id AND s.id=r.supplier_id WHERE r.company_id=c GROUP BY r.id,s.party_id,d.business_date,d.number
 UNION ALL SELECT r.id,r.supplier_id,s.party_id,r.warehouse_id,d.business_date,d.number,'RETURN',-sum(l.cost),0,-sum(l.cost)FROM purchase.returns r JOIN purchase.return_lines l ON l.company_id=r.company_id AND l.return_id=r.id JOIN platform.documents d ON d.company_id=r.company_id AND d.id=r.id JOIN crm.suppliers s ON s.company_id=r.company_id AND s.id=r.supplier_id WHERE r.company_id=c GROUP BY r.id,s.party_id,d.business_date,d.number
 UNION ALL SELECT b.id,b.supplier_id,b.party_id,NULL,d.business_date,d.number,'BILL',b.net,b.tax,b.gross FROM purchase.bills b JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.id WHERE b.company_id=c
 UNION ALL SELECT b.id,b.supplier_id,s.party_id,NULL,d.business_date,d.number,'CREDIT',-b.net,-b.tax,-b.gross FROM purchase.supplier_credit_notes b JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.id JOIN crm.suppliers s ON s.company_id=b.company_id AND s.id=b.supplier_id WHERE b.company_id=c), scoped AS MATERIALIZED(SELECT e.*,p.legal_name FROM events e JOIN crm.parties p ON p.company_id=c AND p.id=e.party_id WHERE e.occurred_on>=p_from AND e.occurred_on<p_to AND(p_party IS NULL OR e.party_id=p_party))
 SELECT jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('documentId',id,'number',number,'date',occurred_on,'eventType',event_type,'supplierId',supplier_id,'partyName',legal_name,'warehouseId',warehouse_id,'net',net::text,'gst',tax::text,'gross',gross::text)ORDER BY occurred_on,id),'[]'),'totals',jsonb_build_object('orderCommitments',coalesce(sum(gross)FILTER(WHERE event_type='ORDER'),0)::text,'receiptsCost',coalesce(sum(gross)FILTER(WHERE event_type='RECEIPT'),0)::text,'returnedCost',coalesce(sum(gross)FILTER(WHERE event_type='RETURN'),0)::text,'netReceiptsCost',coalesce(sum(gross)FILTER(WHERE event_type IN('RECEIPT','RETURN')),0)::text,'bills',coalesce(sum(gross)FILTER(WHERE event_type='BILL'),0)::text,'credits',coalesce(sum(gross)FILTER(WHERE event_type='CREDIT'),0)::text,'netBilled',coalesce(sum(gross)FILTER(WHERE event_type IN('BILL','CREDIT')),0)::text),'status','SOURCE_EVENTS')INTO result FROM scoped;
 ELSIF p_kind IN('ARAP','INVENTORY')THEN
 f:=accounting.close_financials(p_from,p_to);
 IF p_kind='ARAP'THEN
 WITH gl AS(SELECT e->>'controlKind'AS side,nullif(e->>'partyId','')::uuid AS party_id,sum(CASE WHEN e->>'controlKind'='AR'THEN(e->>'balance')::numeric ELSE-(e->>'balance')::numeric END)AS closing,sum(CASE WHEN e->>'controlKind'='AR'THEN(e->>'opening')::numeric ELSE-(e->>'opening')::numeric END)AS opening,sum((e->>'periodDebit')::numeric)AS debits,sum((e->>'periodCredit')::numeric)AS credits FROM jsonb_array_elements(f->'gl')e WHERE e->>'controlKind'IN('AR','AP')GROUP BY 1,2),
 items AS(SELECT e->>'side'AS side,(e->>'partyId')::uuid AS party_id,sum((e->>'balance')::numeric)AS balance FROM jsonb_array_elements(f->'openItems')e GROUP BY 1,2),
 adv AS(SELECT side,party_id,sum(amount)AS advance FROM accounting.report_advance_events WHERE company_id=c AND posting_date<p_to GROUP BY side,party_id),keys AS(SELECT side,party_id FROM gl UNION SELECT side,party_id FROM items UNION SELECT side,party_id FROM adv), rows AS(SELECT k.side,k.party_id,p.legal_name,coalesce(g.opening,0)AS opening,coalesce(g.debits,0)AS debits,coalesce(g.credits,0)AS credits,coalesce(g.closing,0)AS closing,coalesce(i.balance,0)AS business,coalesce(a.advance,0)AS advance FROM keys k LEFT JOIN gl g ON g.side=k.side AND g.party_id IS NOT DISTINCT FROM k.party_id LEFT JOIN items i ON i.side=k.side AND i.party_id IS NOT DISTINCT FROM k.party_id LEFT JOIN adv a ON a.side=k.side AND a.party_id IS NOT DISTINCT FROM k.party_id LEFT JOIN crm.parties p ON p.company_id=c AND p.id=k.party_id WHERE(p_party IS NULL OR k.party_id=p_party))
 SELECT jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('side',side,'partyId',party_id,'partyName',legal_name,'opening',opening::text,'debits',debits::text,'credits',credits::text,'closing',closing::text,'businessBalance',business::text,'difference',(closing-business)::text,'advanceBalance',advance::text)ORDER BY side,party_id),'[]'),'totals',jsonb_build_object('receivables',coalesce(sum(closing)FILTER(WHERE side='AR'),0)::text,'payables',coalesce(sum(closing)FILTER(WHERE side='AP'),0)::text,'customerAdvances',coalesce(sum(advance)FILTER(WHERE side='AR'),0)::text,'supplierAdvances',coalesce(sum(advance)FILTER(WHERE side='AP'),0)::text,'differenceCount',count(*)FILTER(WHERE closing<>business)),'status',CASE WHEN count(*)FILTER(WHERE closing<>business)=0 THEN'RECONCILED'ELSE'UNRECONCILED'END)INTO result FROM rows;
 ELSE
 WITH stock AS(SELECT e FROM jsonb_array_elements(f->'inventory')e WHERE p_warehouse IS NULL OR(e->>'warehouseId')::uuid=p_warehouse), rows AS(SELECT e||jsonb_build_object('positionType','ON_HAND','sku',p.sku,'name',p.name)AS row FROM stock JOIN catalog.products p ON p.company_id=c AND p.id=(e->>'productId')::uuid), transit AS(SELECT e||jsonb_build_object('positionType','IN_TRANSIT','warehouseId',h.destination_id,'sourceWarehouseId',h.source_id,'productId',l.product_id,'sku',p.sku,'name',p.name)AS row FROM jsonb_array_elements(f->'transit')e JOIN inventory.transit_transfer_lines l ON l.company_id=c AND l.id=(e->>'lineId')::uuid JOIN inventory.transit_transfers h ON h.company_id=l.company_id AND h.id=l.transfer_id JOIN catalog.products p ON p.company_id=l.company_id AND p.id=l.product_id WHERE p_warehouse IS NULL OR h.destination_id=p_warehouse),combined AS(SELECT row FROM rows UNION ALL SELECT row FROM transit)
 SELECT jsonb_build_object('rows',coalesce(jsonb_agg(row ORDER BY row->>'positionType',row->>'warehouseId',row->>'productId',row->>'stockBalanceId',row->>'lineId'),'[]'),'totals',jsonb_build_object('onHandValue',coalesce(sum((row->>'value')::numeric)FILTER(WHERE row->>'positionType'='ON_HAND'),0)::text,'inTransitValue',coalesce(sum((row->>'value')::numeric)FILTER(WHERE row->>'positionType'='IN_TRANSIT'),0)::text),'companyInventoryDifference',f->'inventoryDifference','controlCheckScope','COMPANY_WIDE','transitWarehouseBasis','DESTINATION','status',CASE WHEN(f->>'inventoryDifference')::numeric=0 THEN'RECONCILED'ELSE'UNRECONCILED'END)INTO result FROM combined;
 END IF;
 ELSE
 WITH gl AS MATERIALIZED(SELECT b.id,b.name,coalesce(sum(l.debit-l.credit)FILTER(WHERE j.posting_date<p_from),0)AS opening,coalesce(sum(l.debit)FILTER(WHERE j.posting_date>=p_from AND j.posting_date<p_to),0)AS debits,coalesce(sum(l.credit)FILTER(WHERE j.posting_date>=p_from AND j.posting_date<p_to),0)AS credits,coalesce(sum(l.debit-l.credit)FILTER(WHERE j.posting_date<p_to),0)AS closing FROM accounting.bank_accounts b LEFT JOIN accounting.journal_lines l ON l.company_id=b.company_id AND l.account_id=b.id LEFT JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id WHERE b.company_id=c AND(p_bank IS NULL OR b.id=p_bank)GROUP BY b.id),rows AS(SELECT g.*,coalesce((SELECT sum(p.amount-p.reserved_amount)FROM accounting.bank_cash_positions p WHERE p.company_id=c AND p.bank_account_id=g.id AND p.posting_date<p_to),0)AS unallocated_cash,coalesce((SELECT sum(abs(l.amount)-coalesce((SELECT sum(a.amount)FROM accounting.active_bank_matches m JOIN accounting.bank_match_allocations a ON a.company_id=m.company_id AND a.match_id=m.id WHERE m.company_id=c AND m.statement_line_id=l.id),0))FROM accounting.bank_statement_lines l JOIN accounting.bank_statement_controls sc ON sc.company_id=l.company_id AND sc.id=l.statement_id WHERE l.company_id=c AND l.bank_account_id=g.id AND sc.state='OPEN'AND l.transaction_date>=p_from AND l.transaction_date<p_to),0)AS unmatched_statements,(SELECT max(to_date)FROM accounting.active_bank_reconciliations WHERE company_id=c AND bank_account_id=g.id AND to_date<p_to)AS reconciled_to FROM gl g)
 SELECT jsonb_build_object('rows',coalesce(jsonb_agg(jsonb_build_object('bankAccountId',id,'bankName',name,'opening',opening::text,'debits',debits::text,'credits',credits::text,'closing',closing::text,'unallocatedCash',unallocated_cash::text,'unmatchedStatements',unmatched_statements::text,'lastReconciledTo',reconciled_to)ORDER BY id),'[]'),'totals',jsonb_build_object('opening',coalesce(sum(opening),0)::text,'debits',coalesce(sum(debits),0)::text,'credits',coalesce(sum(credits),0)::text,'closing',coalesce(sum(closing),0)::text),'clearingBasis','CURRENT_AT_CAPTURE','status','GL_BALANCES')INTO result FROM rows;
 END IF;
 IF p_kind='ARAP'THEN f:=accounting.advance_control_check(p_to);result:=result||jsonb_build_object('advanceControl',f);IF(f->>'customerDifference')::numeric<>0 OR(f->>'supplierDifference')::numeric<>0 THEN result:=result||jsonb_build_object('status','UNRECONCILED');END IF;END IF;
 IF jsonb_array_length(result->'rows')>5000 OR octet_length(result::text)>4000000 THEN RAISE EXCEPTION 'Report too large; narrow range or filter' USING ERRCODE='HR422';END IF;
 RETURN result||jsonb_build_object('companyId',c,'kind',p_kind,'currency','AUD','basis','POSTING_DATE','from',p_from,'to',p_to,'snapshotAt',statement_timestamp(),'filters',jsonb_build_object('partyId',p_party,'warehouseId',p_warehouse,'bankAccountId',p_bank));
END$$;
CREATE FUNCTION accounting.capture_statement(p_customer uuid,p_from date,p_to date)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();id uuid:=gen_random_uuid();f jsonb;BEGIN
 f:=accounting.statement_snapshot(p_customer,p_from,p_to);IF f->>'status'<>'RECONCILED'THEN RAISE EXCEPTION 'AR source and control account differ; cannot issue a statement' USING ERRCODE='HR409';END IF;
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(id,c,'CUSTOMER_STATEMENT','ST-'||id::text,p_to-1,'CONFIRMED',core.current_actor());
 f:=f||jsonb_build_object('number','ST-'||id::text,'sourceVersion',1,'businessDate',p_to-1,'filename','ST-'||id::text||'.pdf');INSERT INTO accounting.customer_statements(id,company_id,customer_id,from_date,to_date,snapshot,sha256,created_by)VALUES(id,c,p_customer,p_from,p_to,f,encode(sha256(convert_to(f::text,'UTF8')),'hex'),core.current_actor());RETURN id;
END$$;
CREATE FUNCTION accounting.capture_operating_report(p_kind text,p_from date,p_to date,p_party uuid,p_warehouse uuid,p_bank uuid)RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE c uuid:=core.current_company();id uuid:=gen_random_uuid();f jsonb;BEGIN
 f:=accounting.operating_report(p_kind,p_from,p_to,p_party,p_warehouse,p_bank);
 INSERT INTO platform.documents(id,company_id,document_type,number,business_date,state,created_by)VALUES(id,c,'OPERATING_REPORT','RP-'||id::text,p_to-1,'CONFIRMED',core.current_actor());
 INSERT INTO accounting.operating_report_runs(id,company_id,kind,from_date,to_date,filters,snapshot,sha256,created_by)VALUES(id,c,p_kind,p_from,p_to,f->'filters',f,encode(sha256(convert_to(f::text,'UTF8')),'hex'),core.current_actor());RETURN id;
END$$;
CREATE FUNCTION accounting.guard_report_document()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN IF EXISTS(SELECT 1 FROM accounting.customer_statements WHERE company_id=OLD.company_id AND id=OLD.id)OR EXISTS(SELECT 1 FROM accounting.operating_report_runs WHERE company_id=OLD.company_id AND id=OLD.id)THEN RAISE EXCEPTION 'Frozen reporting artifact registry is immutable' USING ERRCODE='23514';END IF;RETURN NEW;END$$;
CREATE TRIGGER report_document_immutable BEFORE UPDATE OR DELETE ON platform.documents FOR EACH ROW EXECUTE FUNCTION accounting.guard_report_document();
GRANT SELECT ON accounting.customer_statements,accounting.operating_report_runs TO htt_app;
REVOKE ALL ON FUNCTION identity.seed_operating_report_roles(uuid),accounting.require_operating_report(text),accounting.statement_snapshot(uuid,date,date),accounting.operating_report(text,date,date,uuid,uuid,uuid),accounting.capture_statement(uuid,date,date),accounting.capture_operating_report(text,date,date,uuid,uuid,uuid),accounting.guard_report_document()FROM PUBLIC;
GRANT EXECUTE ON FUNCTION accounting.require_operating_report(text),accounting.statement_snapshot(uuid,date,date),accounting.operating_report(text,date,date,uuid,uuid,uuid),accounting.capture_statement(uuid,date,date),accounting.capture_operating_report(text,date,date,uuid,uuid,uuid)TO htt_app;

CREATE OR REPLACE FUNCTION platform.require_document_access(doc uuid,action text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE typ text;customer uuid;required text;BEGIN
 required:=CASE action WHEN 'READ' THEN 'documents.files.read' WHEN 'PDF' THEN 'documents.pdf.request' WHEN 'EMAIL' THEN 'documents.email.send' WHEN 'EXPORT' THEN 'reports.operating.export' WHEN 'UPLOAD' THEN 'documents.attachments.write' ELSE NULL END;
 IF required IS NULL THEN RAISE EXCEPTION 'Invalid document action' USING ERRCODE='HD422';END IF;
 PERFORM purchase.require_access(required);
 SELECT document_type INTO typ FROM platform.documents WHERE company_id=core.current_company() AND id=doc AND deleted_at IS NULL AND platform.document_visible(doc);
 IF NOT FOUND THEN RAISE EXCEPTION 'Document unavailable' USING ERRCODE='HT404';END IF;
 IF typ='QUOTE' THEN
  SELECT customer_id INTO customer FROM sales.quotes WHERE company_id=core.current_company() AND id=doc;
  PERFORM sales.require_customer_access('sales.quotes.read',customer);
  IF action='EMAIL' THEN PERFORM purchase.require_access('sales.quotes.send');END IF;
 ELSIF typ='INVOICE' THEN
  SELECT customer_id INTO customer FROM sales.invoices WHERE company_id=core.current_company() AND id=doc;
  PERFORM sales.require_customer_access('sales.invoices.read',customer);
  IF action='EMAIL' THEN PERFORM purchase.require_access('sales.invoices.send');END IF;
 ELSIF typ='PURCHASE_ORDER' THEN
  PERFORM purchase.require_access('purchase.orders.read');PERFORM purchase.require_access('purchase.cost.read');
  IF action='EMAIL' THEN PERFORM purchase.require_access('purchase.orders.send');END IF;
 ELSIF typ='PICK' THEN
 IF action NOT IN('READ','UPLOAD') THEN RAISE EXCEPTION 'Warehouse handover supports private attachments only' USING ERRCODE='HD422';END IF;PERFORM inventory.require_access('inventory.picks.read',(SELECT o.warehouse_id FROM inventory.picks pk JOIN sales.orders o ON o.company_id=pk.company_id AND o.id=pk.order_id WHERE pk.company_id=core.current_company() AND pk.id=doc));
 ELSIF typ IN('SUPPLIER_BILL','SUPPLIER_CREDIT') THEN IF action NOT IN('READ','UPLOAD') THEN RAISE EXCEPTION 'Procurement document supports private attachments only' USING ERRCODE='HD422';END IF;PERFORM purchase.require_access(CASE WHEN typ='SUPPLIER_BILL' THEN 'purchase.bills.read' ELSE 'purchase.credits.read' END);
 ELSIF typ='CUSTOMER_STATEMENT'THEN
 IF action NOT IN('READ','PDF','EMAIL')THEN RAISE EXCEPTION 'Statement supports PDF and authorized mail only' USING ERRCODE='HD422';END IF;
 SELECT customer_id INTO customer FROM accounting.customer_statements WHERE company_id=core.current_company()AND id=doc;PERFORM sales.require_customer_access('accounting.statements.read',customer);PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.reports.read');IF action='EMAIL'THEN PERFORM purchase.require_access('accounting.statements.send');END IF;
 ELSIF typ='OPERATING_REPORT'THEN
 IF action NOT IN('READ','EXPORT')THEN RAISE EXCEPTION 'Operating reports support controlled CSV export only' USING ERRCODE='HD422';END IF;
 PERFORM accounting.require_operating_report((SELECT kind FROM accounting.operating_report_runs WHERE company_id=core.current_company()AND id=doc));PERFORM purchase.require_access('reports.operating.export');
 ELSE RAISE EXCEPTION 'This document type has no file/output workflow yet' USING ERRCODE='HD422';END IF;
 RETURN typ;
END $$;

ALTER TABLE platform.document_jobs DROP CONSTRAINT document_jobs_kind_check;
ALTER TABLE platform.document_jobs ADD CONSTRAINT document_jobs_kind_check CHECK(kind IN('PDF','EMAIL','SCAN','EXPORT'));
ALTER TABLE platform.file_assets DROP CONSTRAINT file_assets_kind_check;
ALTER TABLE platform.file_assets ADD CONSTRAINT file_assets_kind_check CHECK(kind IN('PDF','ATTACHMENT','EXPORT'));
CREATE UNIQUE INDEX document_export_once ON platform.document_jobs(company_id,document_id,source_version)WHERE kind='EXPORT';
CREATE FUNCTION accounting.report_export_payload(p_id uuid)RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE r accounting.operating_report_runs;BEGIN SELECT*INTO r FROM accounting.operating_report_runs WHERE company_id=core.current_company()AND id=p_id;IF NOT FOUND THEN RAISE EXCEPTION 'Report unavailable' USING ERRCODE='HT404';END IF;PERFORM platform.require_document_access(p_id,'EXPORT');RETURN r.snapshot||jsonb_build_object('snapshotHash',r.sha256,'filename','RP-'||r.id::text||'.csv','columns',('{"PURCHASING":[{"key":"date","label":"Date","type":"text"},{"key":"eventType","label":"Event","type":"text"},{"key":"number","label":"Document","type":"text"},{"key":"supplierId","label":"Supplier ID","type":"text"},{"key":"partyName","label":"Supplier","type":"text"},{"key":"warehouseId","label":"Warehouse ID","type":"text"},{"key":"net","label":"Net AUD","type":"decimal"},{"key":"gst","label":"GST AUD","type":"decimal"},{"key":"gross","label":"Gross AUD","type":"decimal"}],"ARAP":[{"key":"side","label":"Side","type":"text"},{"key":"partyId","label":"Party ID","type":"text"},{"key":"partyName","label":"Party","type":"text"},{"key":"opening","label":"Opening AUD","type":"decimal"},{"key":"debits","label":"Debits AUD","type":"decimal"},{"key":"credits","label":"Credits AUD","type":"decimal"},{"key":"closing","label":"Closing AUD","type":"decimal"},{"key":"businessBalance","label":"Business balance AUD","type":"decimal"},{"key":"difference","label":"Difference AUD","type":"decimal"},{"key":"advanceBalance","label":"Advance AUD","type":"decimal"}],"INVENTORY":[{"key":"positionType","label":"Position","type":"text"},{"key":"warehouseId","label":"Warehouse ID","type":"text"},{"key":"productId","label":"Product ID","type":"text"},{"key":"sku","label":"SKU","type":"text"},{"key":"name","label":"Product","type":"text"},{"key":"openingQuantity","label":"Opening qty","type":"decimal"},{"key":"quantityIn","label":"Qty in","type":"decimal"},{"key":"quantityOut","label":"Qty out","type":"decimal"},{"key":"quantity","label":"Closing qty","type":"decimal"},{"key":"openingValue","label":"Opening AUD","type":"decimal"},{"key":"valueIn","label":"Value in AUD","type":"decimal"},{"key":"valueOut","label":"Value out AUD","type":"decimal"},{"key":"value","label":"Closing AUD","type":"decimal"}],"BANKING":[{"key":"bankAccountId","label":"Bank ID","type":"text"},{"key":"bankName","label":"Bank","type":"text"},{"key":"opening","label":"Opening AUD","type":"decimal"},{"key":"debits","label":"Debits AUD","type":"decimal"},{"key":"credits","label":"Credits AUD","type":"decimal"},{"key":"closing","label":"Closing AUD","type":"decimal"},{"key":"unallocatedCash","label":"Unallocated cash AUD","type":"decimal"},{"key":"unmatchedStatements","label":"Unmatched statement AUD","type":"decimal"},{"key":"lastReconciledTo","label":"Reconciled to","type":"text"}]}'::jsonb)->r.kind);END$$;
CREATE FUNCTION accounting.guard_report_work()RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE typ text;expected jsonb;BEGIN
 SELECT document_type INTO typ FROM platform.documents WHERE company_id=NEW.company_id AND id=NEW.document_id;
 IF typ='CUSTOMER_STATEMENT'AND NEW.kind='EMAIL'THEN
 PERFORM platform.require_document_access(NEW.document_id,'EMAIL');PERFORM pg_advisory_xact_lock(hashtextextended('statement-mail:'||NEW.company_id::text||':'||NEW.document_id::text,0));
 IF EXISTS(SELECT 1 FROM platform.document_jobs WHERE company_id=NEW.company_id AND document_id=NEW.document_id AND kind='EMAIL'AND state IN('QUEUED','PROCESSING','RETRY','UNKNOWN'))THEN RAISE EXCEPTION 'Resolve pending or unknown statement delivery before requesting another email' USING ERRCODE='HD409';END IF;RETURN NEW;
 END IF;
 IF typ='CUSTOMER_STATEMENT'AND NEW.kind='PDF'THEN SELECT snapshot INTO expected FROM accounting.customer_statements WHERE company_id=NEW.company_id AND id=NEW.document_id;
 ELSIF typ='OPERATING_REPORT'AND NEW.kind='EXPORT'THEN expected:=accounting.report_export_payload(NEW.document_id);
 ELSIF NEW.kind='EXPORT'OR typ='OPERATING_REPORT'OR typ='CUSTOMER_STATEMENT'AND NEW.kind<>'EMAIL'THEN RAISE EXCEPTION 'Unsupported report output kind' USING ERRCODE='HD422';ELSE RETURN NEW;END IF;
 IF NEW.source_version<>1 OR NEW.payload IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Report output must use the frozen source snapshot' USING ERRCODE='23514';END IF;RETURN NEW;
END$$;
CREATE TRIGGER report_work_source BEFORE INSERT ON platform.document_jobs FOR EACH ROW EXECUTE FUNCTION accounting.guard_report_work();

CREATE OR REPLACE FUNCTION platform.finish_document_work(jid uuid,fence uuid,result text,error_code text,pdf bytea DEFAULT NULL,provider text DEFAULT NULL) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j platform.document_jobs;fid uuid;filename text;BEGIN
 SELECT * INTO j FROM platform.document_jobs WHERE id=jid AND lease_token=fence AND lease_until>now() AND state='PROCESSING' FOR UPDATE;
 IF NOT FOUND THEN RETURN false;END IF;
 IF result NOT IN('SUCCEEDED','RETRY','FAILED','UNKNOWN','REJECTED') OR error_code IS NOT NULL AND error_code!~'^[a-z0-9_]{1,80}$' THEN RAISE EXCEPTION 'Invalid work result' USING ERRCODE='HD422';END IF;
 PERFORM set_config('htt.company_id',j.company_id::text,true);PERFORM set_config('htt.actor_id',j.created_by::text,true);
 IF result='SUCCEEDED' AND j.kind IN('PDF','EXPORT') THEN
  IF j.kind='EXPORT'OR EXISTS(SELECT 1 FROM accounting.customer_statements WHERE company_id=j.company_id AND id=j.document_id)THEN PERFORM platform.require_document_access(j.document_id,j.kind);END IF;
  IF pdf IS NULL OR octet_length(pdf) NOT BETWEEN 8 AND 10485760 OR(j.kind='PDF'AND substring(pdf FROM 1 FOR 5)<>convert_to('%PDF-','UTF8'))OR(j.kind='EXPORT'AND substring(pdf FROM 1 FOR 3)<>decode('efbbbf','hex'))THEN RAISE EXCEPTION 'Invalid generated PDF' USING ERRCODE='HD422';END IF;
  fid:=gen_random_uuid();filename:=j.payload->>'filename';
  INSERT INTO platform.files(id,company_id,object_key,content_type,size_bytes,sha256,state,created_by) VALUES(fid,j.company_id,j.company_id::text||'/'||fid::text,CASE WHEN j.kind='PDF'THEN'application/pdf'ELSE'text/csv; charset=utf-8'END,octet_length(pdf),encode(sha256(pdf),'hex'),'VERIFIED',j.created_by);
  INSERT INTO platform.file_contents(company_id,file_id,body) VALUES(j.company_id,fid,pdf);
  INSERT INTO platform.file_assets(company_id,file_id,document_id,source_version,filename,kind) VALUES(j.company_id,fid,j.document_id,j.source_version,filename,CASE WHEN j.kind='PDF'THEN'PDF'ELSE'EXPORT'END);
  INSERT INTO platform.file_links(company_id,file_id,document_id,created_by) VALUES(j.company_id,fid,j.document_id,j.created_by);
 ELSIF j.kind='SCAN' AND result IN('SUCCEEDED','REJECTED') THEN
  fid:=(j.payload->>'fileId')::uuid;
  UPDATE platform.files SET state=CASE WHEN result='SUCCEEDED' THEN 'VERIFIED' ELSE 'REJECTED' END WHERE company_id=j.company_id AND id=fid AND state='PENDING';
 ELSIF result='SUCCEEDED' AND j.kind='EMAIL' AND (provider IS NULL OR length(provider) NOT BETWEEN 1 AND 200) THEN RAISE EXCEPTION 'Provider receipt required' USING ERRCODE='HD422';
 END IF;
 UPDATE platform.document_job_attempts SET finished_at=now(),result=finish_document_work.result,error_code=finish_document_work.error_code WHERE company_id=j.company_id AND job_id=j.id AND lease_token=fence;
 UPDATE platform.document_jobs SET state=CASE WHEN result='REJECTED' THEN 'FAILED' WHEN result='RETRY' AND attempts>=5 THEN 'FAILED' ELSE result END,
  output_file_id=coalesce(fid,output_file_id),provider_id=provider,last_error=error_code,
  completed_at=CASE WHEN result='SUCCEEDED' THEN now() END,available_at=now()+make_interval(secs=>least(900,15*power(2,attempts)::int)),lease_token=NULL,lease_until=NULL WHERE id=j.id;
 INSERT INTO platform.audit_events(company_id,actor_id,action,entity_type,entity_id,request_id,details)
  VALUES(j.company_id,j.created_by,'documents.work_finished','document_job',j.id,'document-worker',jsonb_build_object('kind',j.kind,'result',result,'errorCode',error_code,'attempt',j.total_attempts));
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION accounting.report_export_payload(uuid),accounting.guard_report_work()FROM PUBLIC;
GRANT EXECUTE ON FUNCTION accounting.report_export_payload(uuid)TO htt_app;
